/**
 * ExportConfirmModal — confirm dialog for choosing export scope.
 *
 * Two options:
 *   1. Xuất trang hiện tại  — client-side xlsx via onExportCurrent callback
 *   2. Xuất tất cả theo lọc — calls backend, triggers browser download via onExportAll callback
 */
import React, { useState } from 'react';
import styles from './ExportConfirmModal.module.css';

export interface ExportConfirmModalProps {
  isOpen:           boolean;
  onClose:          () => void;
  currentPageCount: number;
  totalCount:       number;
  /** Called when user picks "Xuất trang hiện tại" — should call client-side xlsx */
  onExportCurrent:  () => void;
  /** Called when user picks "Xuất tất cả" — should POST to backend and download */
  onExportAll:      () => Promise<void>;
}

export const ExportConfirmModal: React.FC<ExportConfirmModalProps> = ({
  isOpen,
  onClose,
  currentPageCount,
  totalCount,
  onExportCurrent,
  onExportAll,
}) => {
  const [exportingAll, setExportingAll] = useState(false);

  if (!isOpen) return null;

  const MAX_ROWS = 50_000;
  const showExportAll = totalCount > currentPageCount;
  const exceedsLimit  = totalCount > MAX_ROWS;

  const handleExportCurrent = () => {
    onExportCurrent();
    onClose();
  };

  const handleExportAll = async () => {
    if (exceedsLimit) return;
    setExportingAll(true);
    try {
      await onExportAll();
      onClose();
    } finally {
      setExportingAll(false);
    }
  };

  return (
    <div className={styles.overlay} onClick={onClose}>
      <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className={styles.header}>
          <h3 className={styles.title}>
            <i className="fas fa-file-excel" />
            {' '}Xuất dữ liệu Excel
          </h3>
          <button className={styles.closeBtn} onClick={onClose} disabled={exportingAll}>
            <i className="fas fa-times" />
          </button>
        </div>

        {/* Body */}
        <div className={styles.body}>
          <p className={styles.description}>
            Chọn phạm vi dữ liệu bạn muốn xuất:
          </p>

          {/* Option 1: current page */}
          <button
            className={styles.optionCard}
            onClick={handleExportCurrent}
            disabled={exportingAll || currentPageCount === 0}
          >
            <div className={styles.optionIcon}>
              <i className="fas fa-file-alt" />
            </div>
            <div className={styles.optionContent}>
              <span className={styles.optionTitle}>Xuất trang hiện tại</span>
              <span className={styles.optionDesc}>
                {currentPageCount} bản ghi đang hiển thị
              </span>
            </div>
            <i className="fas fa-chevron-right" />
          </button>

          {/* Option 2: all by filter — only shown when total > current page */}
          {showExportAll && (
            <button
              className={`${styles.optionCard} ${exceedsLimit ? styles.optionCardDisabled : ''}`}
              onClick={handleExportAll}
              disabled={exportingAll || exceedsLimit}
            >
              <div className={`${styles.optionIcon} ${styles.optionIconPrimary}`}>
                {exportingAll
                  ? <i className="fas fa-spinner fa-spin" />
                  : <i className="fas fa-database" />}
              </div>
              <div className={styles.optionContent}>
                <span className={styles.optionTitle}>
                  {exportingAll ? 'Đang tạo file…' : 'Xuất tất cả theo điều kiện lọc'}
                </span>
                {exceedsLimit ? (
                  <span className={styles.optionDescWarning}>
                    <i className="fas fa-exclamation-triangle" />{' '}
                    Dữ liệu vượt giới hạn cho phép {MAX_ROWS.toLocaleString('vi-VN')} bản ghi
                  </span>
                ) : (
                  <span className={styles.optionDesc}>
                    {(totalCount ?? 0).toLocaleString('vi-VN')} bản ghi
                  </span>
                )}
              </div>
              {!exportingAll && !exceedsLimit && <i className="fas fa-chevron-right" />}
            </button>
          )}
        </div>

        {/* Footer */}
        <div className={styles.footer}>
          <button className={styles.cancelBtn} onClick={onClose} disabled={exportingAll}>
            Hủy
          </button>
        </div>
      </div>
    </div>
  );
};
