/**
 * MonthYearPill — pill button with floating dropdown picker
 *
 * The pill button always stays the same shape showing the current label
 * e.g. "Tháng 4/2026" or "Năm 2026".
 * Clicking the pill toggles a small floating dropdown below it
 * containing the native month or year picker.
 */
import React, { useEffect, useRef, useState } from 'react';
import styles from './MonthYearPill.module.css';

interface MonthYearPillProps {
  type:    'month' | 'year';
  active:  boolean;
  /** YYYY-MM for month, "YYYY" string for year */
  value:   string;
  onChange:   (value: string) => void;
  onActivate: () => void;
  /** Max value (YYYY-MM for month) */
  max?:    string;
  minYear?: number;
  maxYear?: number;
}

const CURRENT_YEAR = new Date().getFullYear();

function formatLabel(type: 'month' | 'year', value: string): string {
  if (type === 'month') {
    const [y, m] = value.split('-').map(Number);
    if (!y || !m) return 'Tháng';
    return `Tháng ${m}/${y}`;
  }
  return `Năm ${value || CURRENT_YEAR}`;
}

function buildYearOptions(min: number, max: number): number[] {
  const years: number[] = [];
  for (let y = max; y >= min; y--) years.push(y);
  return years;
}

export const MonthYearPill: React.FC<MonthYearPillProps> = ({
  type,
  active,
  value,
  onChange,
  onActivate,
  max,
  minYear = 2000,
  maxYear = CURRENT_YEAR + 1,
}) => {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // When this pill becomes active (user clicked it in DateRangeFilter)
  // open the dropdown immediately
  useEffect(() => {
    if (active) setOpen(true);
    else        setOpen(false);
  }, [active]);

  // Auto-focus the inner input when dropdown opens
  useEffect(() => {
    if (open && type === 'month') {
      const t = setTimeout(() => inputRef.current?.showPicker?.(), 50);
      return () => clearTimeout(t);
    }
  }, [open, type]);

  // Close on outside click
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDown);
    return () => document.removeEventListener('mousedown', onDown);
  }, [open]);

  const handlePillClick = () => {
    if (!active) onActivate();
    else setOpen((v) => !v);
  };

  const label = formatLabel(type, value);

  return (
    <div ref={wrapRef} className={styles.pillWrapper}>
      {/* Pill button — always same shape */}
      <button
        type="button"
        className={`${styles.pill} ${active ? styles.pillActive : ''}`}
        onClick={handlePillClick}
        title={type === 'month' ? 'Lọc theo tháng' : 'Lọc theo năm'}
      >
        {label}
        <i className={`fas fa-chevron-${open ? 'up' : 'down'} ${styles.pillChevron}`} />
      </button>

      {/* Floating dropdown */}
      {open && (
        <div className={styles.dropdown}>
          {type === 'month' ? (
            <input
              ref={inputRef}
              type="month"
              className={styles.dropdownInput}
              value={value}
              max={max}
              onChange={(e) => {
                if (e.target.value) {
                  onChange(e.target.value);
                  setOpen(false);
                }
              }}
              aria-label="Chọn tháng"
            />
          ) : (
            <select
              className={styles.dropdownSelect}
              value={value}
              onChange={(e) => {
                onChange(e.target.value);
                setOpen(false);
              }}
              size={Math.min(8, maxYear - minYear + 1)}
              aria-label="Chọn năm"
            >
              {buildYearOptions(minYear, maxYear).map((y) => (
                <option key={y} value={String(y)}>{y}</option>
              ))}
            </select>
          )}
        </div>
      )}
    </div>
  );
};

