import React, { useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { useNavTitle } from '@linm-soft/common-components';
import { stripAppPrefix } from '../../../config/appRoutes';

function resolvePageTitle(pathname: string): string {
  const path = stripAppPrefix(pathname);
  if (path === '/tickets') return 'Phiếu yêu cầu';
  if (path === '/tasks') return 'Công việc của tôi';
  if (path === '/task-pool') return 'Công việc chờ nhận';
  if (path === '/department-tasks') return 'Công việc phòng ban';
  if (path === '/approvals') return 'Phê duyệt';
  if (path === '/sla-alerts') return 'Cảnh báo SLA';
  if (path === '/reports') return 'Báo cáo & Phân tích';
  if (path === '/statistics') return 'Thống kê';
  if (path === '/history') return 'Lịch sử';
  if (path === '/admin/users') return 'Quản lý người dùng';
  if (path === '/admin/departments') return 'Quản lý phòng ban';
  if (path === '/medical-incidents') return 'Danh Sách Sự Cố Y Khoa';
  if (path === '/medical-incidents/reports') return 'Báo Cáo Thống Kê SCYK';
  if (path === '/medical-incidents/reports/service-mismatch') return 'Báo Cáo Nhầm Dịch Vụ';
  if (path === '/medical-incidents/reports/fall') return 'Báo Cáo Sự Cố Té Ngã';
  if (path === '/medical-incidents/new') return 'Báo Cáo Sự Cố Mới';
  if (path.startsWith('/medical-incidents/daily-reports')) return 'Báo Cáo Hằng Ngày';
  if (path.startsWith('/medical-incidents/')) return 'Chi Tiết Sự Cố';
  if (path === '/fall-location-warnings') return 'Cảnh Báo Vị Trí Té Ngã';
  if (path === '/fall-location-warnings/new') return 'Thêm Cảnh Báo Vị Trí Té Ngã';
  if (path.startsWith('/fall-location-warnings/')) return 'Chi Tiết Cảnh Báo Vị Trí Té Ngã';
  if (path.startsWith('/tickets/')) return 'Chi tiết phiếu';
  if (path.startsWith('/tasks/')) return 'Chi tiết công việc';
  return 'QLCV & SC Y Khoa';
}

/** Publishes page title to @linm/nav Topbar (`linm:nav:set-title`). */
export const RouteNavTitleSync: React.FC = () => {
  const { pathname } = useLocation();
  const title = useMemo(() => resolvePageTitle(pathname), [pathname]);
  useNavTitle(title);
  return null;
};

export default RouteNavTitleSync;
