import React, { useEffect, useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { appPath } from '../../config/appRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { fetchDepartmentTasks, claimDepartmentTask } from '../../store/slices/tasksSlice';
import { Task, TaskPriority } from '../../models/Task';
import { Badge } from '../../components/common/Badge';
import { Button } from '../../components/common/Button';
import { SLABadge } from '../../components/common/SLABadge';
import { TableCard, Select, StatsCard, StatsCardsGrid } from '../../components/common';
import { useAppToast } from '../../hooks/useAppToast';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './DepartmentTasksPage.module.css';

const DepartmentTasksPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const toast = useAppToast();
  const { departmentTasks, loading } = useAppSelector((state) => state.tasks);
  const { user } = useAppSelector((state) => state.auth);
  const { taskPriorityOptions, taskSkillOptions, deadlineFilterOptions, taskSortOrderOptions } = useFormOptions('department-tasks');
  const [searchQuery, setSearchQuery] = useState('');
  const [filters, setFilters] = useState({
    priority: 'all',
    skills: 'all',
    deadline: 'all',
    sort: 'priority',
  });
  const [claiming, setClaiming] = useState<string | null>(null);
  const showLoading = useMinLoadingTime(loading);

  // Stats derived from all department tasks
  const stats = useMemo(() => ({
    total:    departmentTasks.length,
    critical: departmentTasks.filter((t) => t.priority === TaskPriority.Critical).length,
    high:     departmentTasks.filter((t) => t.priority === TaskPriority.High).length,
    dueSoon:  departmentTasks.filter((t) => t.slaRemaining != null && t.slaRemaining < 240).length,
  }), [departmentTasks]);

  useEffect(() => {
    if (!user?.departmentId) return;
    const timer = setTimeout(() => { dispatch(fetchDepartmentTasks(user.departmentId!)); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, user]);

  const handleClaimTask = async (taskId: string) => {
    setClaiming(taskId);
    try {
      await dispatch(claimDepartmentTask(taskId)).unwrap();
      toast.success('Nhận công việc thành công!');
      // Navigate to task detail after claiming
      navigate(appPath(`tasks/${taskId}`));
    } catch (error: unknown) {
      toast.fromError(error, 'Không thể nhận task. Vui lòng thử lại!');
    } finally {
      setClaiming(null);
    }
  };

  const handleViewDetails = (taskId: string) => {
    navigate(appPath(`tasks/${taskId}`));
  };

  const getPriorityBadgeVariant = (priority: TaskPriority) => {
    switch (priority) {
      case TaskPriority.Critical:
        return 'danger';
      case TaskPriority.High:
        return 'warning';
      case TaskPriority.Medium:
        return 'info';
      case TaskPriority.Low:
        return 'success';
    }
  };

  const getPriorityLabel = (priority: TaskPriority): string =>
    taskPriorityOptions.find((o) => o.value === priority)?.label ?? priority;

  const getSLAStatus = (slaRemaining?: number) => {
    if (!slaRemaining) return 'safe';
    if (slaRemaining < 60) return 'danger';
    if (slaRemaining < 240) return 'warning';
    return 'safe';
  };

  const formatSLATime = (minutes?: number): string => {
    if (!minutes) return 'N/A';
    if (minutes < 60) return `${minutes}m`;
    if (minutes < 1440) return `${Math.floor(minutes / 60)}h`;
    return `${Math.floor(minutes / 1440)} ngày`;
  };

  const formatTimeAssigned = (createdAt: string): string => {
    return formatDistanceToNow(new Date(createdAt), { locale: vi, addSuffix: false });
  };

  const getFilteredTasks = () => {
    let filtered = [...departmentTasks];

    // Search filter
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (task: Task) =>
          task.title.toLowerCase().includes(query) ||
          task.description.toLowerCase().includes(query) ||
          task.skillsRequired?.some((skill: string) => skill.toLowerCase().includes(query))
      );
    }

    // Priority filter
    if (filters.priority !== 'all') {
      filtered = filtered.filter((task) => task.priority === filters.priority);
    }

    // Skills filter
    if (filters.skills !== 'all') {
      filtered = filtered.filter((task: Task) =>
        task.skillsRequired?.some((skill: string) => skill === filters.skills)
      );
    }

    // Deadline filter
    if (filters.deadline !== 'all') {
      const now = new Date();
      filtered = filtered.filter((task) => {
        const dueDate = new Date(task.dueDate);
        const diffHours = (dueDate.getTime() - now.getTime()) / (1000 * 60 * 60);

        switch (filters.deadline) {
          case 'today':
            return diffHours <= 24;
          case 'week':
            return diffHours <= 168;
          case 'month':
            return diffHours <= 720;
          default:
            return true;
        }
      });
    }

    // Sort
    filtered.sort((a: Task, b: Task) => {
      switch (filters.sort) {
        case 'priority':
          const priorityOrder: Record<TaskPriority, number> = {
            [TaskPriority.Critical]: 0,
            [TaskPriority.High]: 1,
            [TaskPriority.Medium]: 2,
            [TaskPriority.Low]: 3,
          };
          return priorityOrder[a.priority] - priorityOrder[b.priority];
        case 'deadline':
          return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
        case 'estimate':
          return a.estimatedHours - b.estimatedHours;
        case 'newest':
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        default:
          return 0;
      }
    });

    return filtered;
  };

  const filteredTasks = getFilteredTasks();

  return (
    <div className={styles.page}>
      {/* 1. Page Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-building" />
          Công Việc Phòng Ban
          {user?.departmentName && (
            <span className={styles.deptNameTag}>{user.departmentName}</span>
          )}
        </h1>
      </div>

      {/* 2. Stats Cards */}
      <StatsCardsGrid>
        <StatsCard label="Tổng công việc" value={stats.total}      icon="fas fa-tasks"              variant="total"   loading={showLoading} />
        <StatsCard label="Khẩn cấp"         value={stats.critical}   icon="fas fa-exclamation-circle" variant="danger"  loading={showLoading} />
        <StatsCard label="Ưu tiên cao"       value={stats.high}       icon="fas fa-arrow-up"           variant="warning" loading={showLoading} />
        <StatsCard label="Sắp hết hạn"      value={stats.dueSoon}   icon="fas fa-clock"              variant="gray"    loading={showLoading} />
      </StatsCardsGrid>

      {/* 3. TableCard: Filters + Grid */}
      <TableCard
        header={
          <div className={styles.filtersBar}>
            <span className={styles.filtersTitle}>
              <i className="fas fa-filter" /> Bộ lọc
            </span>
            <div className={styles.searchWrapper}>
              <i className="fas fa-search" />
              <input
                type="text"
                className={styles.searchInput}
                placeholder="Tìm task theo keywords, skills..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            <Select
              value={filters.priority}
              onChange={(e) => setFilters({ ...filters, priority: e.target.value })}
              options={[{ value: 'all', label: 'Tất cả ưu tiên' }, ...taskPriorityOptions.map((o) => ({ value: String(o.value), label: o.label }))]}
              placeholder="Ưu tiên"
            />
            <Select
              value={filters.skills}
              onChange={(e) => setFilters({ ...filters, skills: e.target.value })}
              options={[{ value: 'all', label: 'Tất cả kỹ năng' }, ...taskSkillOptions.map((o) => ({ value: String(o.value), label: o.label }))]}
              placeholder="Kỹ năng"
            />
            <Select
              value={filters.deadline}
              onChange={(e) => setFilters({ ...filters, deadline: e.target.value })}
              options={[{ value: 'all', label: 'Tất cả thời hạn' }, ...deadlineFilterOptions.map((o) => ({ value: String(o.value), label: o.label }))]}
              placeholder="Thời hạn"
            />
            <Select
              value={filters.sort}
              onChange={(e) => setFilters({ ...filters, sort: e.target.value })}
              options={taskSortOrderOptions.map((o) => ({ value: String(o.value), label: o.label }))}
              placeholder="Sắp xếp"
            />
          </div>
        }
      >
        {/* Skeleton */}
        {showLoading && (
          <div className={styles.skeletonGrid}>
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className={styles.skeletonCard}>
                <div className={styles.skeletonPulse} style={{ width: '40%', height: 12 }} />
                <div className={styles.skeletonPulse} style={{ width: '80%', height: 18, marginTop: 8 }} />
                <div className={styles.skeletonPulse} style={{ width: '90%', height: 14, marginTop: 6 }} />
                <div className={styles.skeletonPulse} style={{ width: '60%', height: 14, marginTop: 4 }} />
                <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
                  <div className={styles.skeletonPulse} style={{ flex: 1, height: 32, borderRadius: 6 }} />
                  <div className={styles.skeletonPulse} style={{ width: 40, height: 32, borderRadius: 6 }} />
                </div>
              </div>
            ))}
          </div>
        )}

        {!showLoading && filteredTasks.length === 0 && (
          <div className={styles.emptyState}>
            <i className="fas fa-inbox"></i>
            <h3>Không có công việc nào</h3>
            <p>
              Hiện tại không có công việc nào được giao cho phòng {user?.departmentName} hoặc tất
              cả đã được nhận.
            </p>
          </div>
        )}

        {!showLoading && filteredTasks.length > 0 && (
          <div className={styles.tasksGrid}>
            {filteredTasks.map((task) => (
              <div
                key={task.id}
                className={styles.taskCard}
                style={{
                  borderLeftColor:
                    task.priority === TaskPriority.Critical
                      ? 'var(--danger)'
                      : task.priority === TaskPriority.High
                      ? 'var(--warning)'
                      : 'var(--info)',
                }}
              >
                <div className={styles.cardHeader}>
                  <div>
                    <div className={styles.taskId}>{task.idCode || task.id}</div>
                    <h4 className={styles.taskTitle}>{task.title}</h4>
                  </div>
                  <Badge variant={getPriorityBadgeVariant(task.priority)}>
                    <i className="fas fa-exclamation-circle"></i> {getPriorityLabel(task.priority)}
                  </Badge>
                </div>

                <p className={styles.taskDescription}>{task.description}</p>

                {/* Skills */}
                {task.skillsRequired && task.skillsRequired.length > 0 && (
                  <div className={styles.skillsBadges}>
                    {task.skillsRequired.map((skill: string, index: number) => (
                      <Badge key={index} variant="primary">
                        <i className="fas fa-tools"></i> {skill}
                      </Badge>
                    ))}
                  </div>
                )}

                {/* Metrics */}
                <div className={styles.metricsGrid}>
                  <div className={styles.metricItem}>
                    <div className={styles.metricLabel}>HẠN CHỐT</div>
                    <div className={styles.metricValue}>
                      <i className="fas fa-clock"></i> {formatSLATime(task.slaRemaining)}
                    </div>
                  </div>
                  <div className={styles.metricItem}>
                    <div className={styles.metricLabel}>ESTIMATE</div>
                    <div className={styles.metricValue}>
                      <i className="fas fa-hourglass-half"></i> {task.estimatedHours}h
                    </div>
                  </div>
                  <div className={styles.metricItem}>
                    <div className={styles.metricLabel}>Trạng thái SLA</div>
                    <SLABadge
                      status={getSLAStatus(task.slaRemaining)}
                      timeRemaining={getSLAStatus(task.slaRemaining).toUpperCase()}
                    />
                  </div>
                  <div className={styles.metricItem}>
                    <div className={styles.metricLabel}>ĐƯỢC GIAO</div>
                    <div className={styles.metricValue}>
                      <i className="fas fa-clock"></i> {formatTimeAssigned(task.createdAt)}
                    </div>
                  </div>
                </div>

                {/* Actions */}
                <div className={styles.cardActions}>
                  <Button
                    variant={
                      task.priority === TaskPriority.Critical
                        ? 'danger'
                        : task.priority === TaskPriority.High
                        ? 'warning'
                        : 'primary'
                    }
                    onClick={() => handleClaimTask(task.id)}
                    disabled={claiming === task.id}
                  >
                    {claiming === task.id ? (
                      <>
                        <i className="fas fa-spinner fa-spin"></i> Đang nhận...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-hand-paper"></i> Tôi nhận công việc này
                      </>
                    )}
                  </Button>
                  <Button variant="secondary" onClick={() => handleViewDetails(task.id)}>
                    <i className="fas fa-info-circle"></i>
                  </Button>
                </div>

                {/* Footer */}
                <div className={styles.cardFooter}>
                  <i className="fas fa-clock"></i>
                  Giao {formatTimeAssigned(task.createdAt)} trước bởi{' '}
                  <strong>{task.creatorName}</strong>
                </div>
              </div>
            ))}
          </div>
        )}
      </TableCard>
    </div>
  );
};

export default DepartmentTasksPage;
