import React from 'react';
import { StatsCard, StatsCardsGrid } from '../../common';
import { SLAStats, SLASeverity } from '../../../models/SLAAlert';

interface AlertsStatsCardsProps {
  stats: SLAStats | null;
  loading?: boolean;
  activeFilter?: string;
  onFilter?: (severity: string) => void;
}

export const AlertsStatsCards: React.FC<AlertsStatsCardsProps> = ({
  stats,
  loading,
  activeFilter = 'all',
  onFilter,
}) => {
  const handleClick = (severity: string) => {
    if (!onFilter) return;
    onFilter(activeFilter === severity ? 'all' : severity);
  };

  return (
    <StatsCardsGrid>
      <StatsCard
        label="Tất cả hoạt động"
        value={stats?.totalActive ?? 0}
        variant="total"
        loading={loading}
        active={activeFilter === 'all'}
        onClick={() => handleClick('all')}
      />
      <StatsCard
        label="Vi phạm SLA"
        value={stats?.breached ?? 0}
        variant="danger"
        loading={loading}
        active={activeFilter === SLASeverity.Breached}
        onClick={() => handleClick(SLASeverity.Breached)}
      />
      <StatsCard
        label="Nguy cơ cao"
        value={stats?.danger ?? 0}
        variant="warning"
        loading={loading}
        active={activeFilter === SLASeverity.Danger}
        onClick={() => handleClick(SLASeverity.Danger)}
      />
      <StatsCard
        label="Cảnh báo"
        value={stats?.warning ?? 0}
        variant="info"
        loading={loading}
        active={activeFilter === SLASeverity.Warning}
        onClick={() => handleClick(SLASeverity.Warning)}
      />
      <StatsCard
        label="Theo dõi"
        value={stats?.watch ?? 0}
        variant="gray"
        loading={loading}
        active={activeFilter === SLASeverity.Watch}
        onClick={() => handleClick(SLASeverity.Watch)}
      />
      <StatsCard
        label="Tuân thủ SLA"
        value={`${stats?.complianceRate ?? 0}%`}
        variant="success"
        loading={loading}
      />
    </StatsCardsGrid>
  );
};
