/** UI path segment — distinguishes @linm/m-inc routes from other MFEs on the Linm shell. */
export const APP_UI_PREFIX = 'm-inc';

/** Absolute in-app path: `/m-inc/...` (API URLs are unchanged). */
export function appPath(path = ''): string {
  const trimmed = path.replace(/^\/+/, '');
  if (!trimmed) return `/${APP_UI_PREFIX}`;
  if (trimmed === APP_UI_PREFIX || trimmed.startsWith(`${APP_UI_PREFIX}/`)) {
    return `/${trimmed}`;
  }
  return `/${APP_UI_PREFIX}/${trimmed}`;
}

/** Menu / Auth paths may omit the prefix — normalize for navigation. */
export function resolveAppPath(path: string): string {
  if (!path || path === '/') return appPath('tickets');
  return appPath(path);
}

/** Compare permission menu paths (often without prefix) to the current URL. */
export function stripAppPrefix(pathname: string): string {
  const base = pathname.replace(/\/+$/, '') || '/';
  const prefix = `/${APP_UI_PREFIX}`;
  if (base === prefix) return '/';
  if (base.startsWith(`${prefix}/`)) return base.slice(prefix.length) || '/';
  return base;
}
