import React from 'react';
import { TeamComparison as TeamComparisonType } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import styles from './TeamComparison.module.css';

interface TeamComparisonProps {
  data: {
    completionRate: TeamComparisonType;
    averageTime: TeamComparisonType;
    qualityScore: TeamComparisonType;
  };
}

export const TeamComparison: React.FC<TeamComparisonProps> = ({ data }) => {
  const renderComparisonItem = (comparison: TeamComparisonType) => {
    const isPositive = comparison.betterThanTeam;
    const icon = isPositive ? 'fas fa-arrow-up' : 'fas fa-arrow-down';
    const color = isPositive ? 'var(--success-color)' : 'var(--danger-color)';

    return (
      <div className={styles.comparisonItem}>
        <div className={styles.metric}>{comparison.metric}</div>
        <div className={styles.values}>
          <div className={styles.valueRow}>
            <span className={styles.label}>Bạn:</span>
            <span className={styles.value}>{comparison.myAverage}</span>
          </div>
          <div className={styles.valueRow}>
            <span className={styles.label}>Team TB:</span>
            <span className={styles.value}>{comparison.teamAverage}</span>
          </div>
        </div>
        <div className={styles.difference} style={{ color }}>
          <i className={icon}></i>
          {Math.abs(comparison.difference).toFixed(1)}%
        </div>
      </div>
    );
  };

  return (
    <Card className={styles.comparisonCard}>
      <h3 className={styles.title}>
        <i className="fas fa-users" style={{ color: 'var(--info-color)' }}></i>
        So Sánh Với Team
      </h3>
      <div className={styles.comparisonList}>
        {renderComparisonItem(data.completionRate)}
        {renderComparisonItem(data.averageTime)}
        {renderComparisonItem(data.qualityScore)}
      </div>
    </Card>
  );
};
