import React, { useState, useRef } from 'react';
import { Task, TaskPriority } from '../../../models/Task';
import { Badge } from '../../../components/common/Badge';
import { SLABadge } from '../../../components/common/SLABadge';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './TaskCard.module.css';

interface TaskCardProps {
  task: Task;
  onDragStart: () => void;
  onDragEnd: () => void;
  onClick: () => void;
}

export const TaskCard: React.FC<TaskCardProps> = ({
  task,
  onDragStart,
  onDragEnd,
  onClick,
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isDraggable, setIsDraggable] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const longPressTimer = useRef<NodeJS.Timeout | null>(null);
  const { taskPriorityOptions } = useFormOptions('display-labels');

  const getPriorityClass = () => {
    switch (task.priority) {
      case TaskPriority.Critical:
        return styles.priorityCritical;
      case TaskPriority.High:
        return styles.priorityHigh;
      case TaskPriority.Medium:
        return styles.priorityMedium;
      case TaskPriority.Low:
        return styles.priorityLow;
      default:
        return '';
    }
  };

  const getPriorityBadge = () => {
    const label = taskPriorityOptions.find((o) => o.value === task.priority)?.label ?? task.priority;
    switch (task.priority) {
      case TaskPriority.Critical:
        return <Badge variant="danger" size="sm">{label}</Badge>;
      case TaskPriority.High:
        return <Badge variant="warning" size="sm">{label}</Badge>;
      case TaskPriority.Medium:
        return <Badge variant="info" size="sm">{label}</Badge>;
      case TaskPriority.Low:
        return <Badge variant="success" size="sm">{label}</Badge>;
      default:
        return <Badge size="sm">{label}</Badge>;
    }
  };

  const getSLAStatus = () => {
    if (!task.slaRemaining) return 'safe';
    if (task.slaRemaining < 60) return 'danger';
    if (task.slaRemaining < 240) return 'warning';
    return 'safe';
  };

  const formatSLATime = (minutes?: number): string => {
    if (!minutes) return 'N/A';
    if (minutes < 60) return `${minutes}m`;
    if (minutes < 1440) return `${Math.floor(minutes / 60)}h`;
    return `${Math.floor(minutes / 1440)} ngày`;
  };

  const handleDragStart = (e: React.DragEvent) => {
    if (!isDraggable) {
      e.preventDefault();
      return;
    }
    setIsDragging(true);
    onDragStart();
  };

  const handleDragEnd = () => {
    setIsDragging(false);
    setIsDraggable(false);
    onDragEnd();
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Only left click
    if (e.button !== 0) return;
    
    setStartPos({ x: e.clientX, y: e.clientY });
    
    longPressTimer.current = setTimeout(() => {
      setIsDraggable(true);
      // Haptic feedback on supported devices
      if ('vibrate' in navigator) {
        navigator.vibrate(50);
      }
    }, 500); // 500ms long press
  };

  const handleMouseUp = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
    }
    
    setIsDraggable(false);
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    const touch = e.touches[0];
    setStartPos({ x: touch.clientX, y: touch.clientY });
    
    longPressTimer.current = setTimeout(() => {
      setIsDraggable(true);
      // Haptic feedback on supported devices
      if ('vibrate' in navigator) {
        navigator.vibrate(50);
      }
    }, 500); // 500ms long press
  };

  const handleTouchEnd = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
    }
    
    setIsDraggable(false);
  };

  const handleIdClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!isDragging && !isDraggable) {
      onClick();
    }
  };

  return (
    <div
      className={`${styles.taskCard} ${getPriorityClass()} ${
        isDragging ? styles.dragging : ''
      } ${isDraggable ? styles.grabbable : ''}`}
      draggable={isDraggable}
      onDragStart={handleDragStart}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onDragEnd={handleDragEnd}
      onMouseMove={(e) => {
        // Cancel long press if user moves mouse (panning board)
        const diffX = Math.abs(e.clientX - startPos.x);
        const diffY = Math.abs(e.clientY - startPos.y);
        if ((diffX > 5 || diffY > 5) && longPressTimer.current) {
          clearTimeout(longPressTimer.current);
          longPressTimer.current = null;
        }
      }}
      onTouchMove={(e) => {
        // Cancel long press if user moves finger (swiping)
        const touch = e.touches[0];
        const diffX = Math.abs(touch.clientX - startPos.x);
        const diffY = Math.abs(touch.clientY - startPos.y);
        if ((diffX > 5 || diffY > 5) && longPressTimer.current) {
          clearTimeout(longPressTimer.current);
          longPressTimer.current = null;
        }
      }}
    >
      <div className={styles.cardHeader}>
        <span 
          className={styles.taskId}
          onClick={handleIdClick}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              onClick();
            }
          }}
        >
          {task.idCode || task.id.substring(0, 8)}
        </span>
        {getPriorityBadge()}
      </div>
      <div className={styles.cardTitle}>{task.title}</div>
      {task.status !== 'completed' && (
        <div className={styles.cardProgress}>
          <div className={styles.progressInfo}>
            <span>Progress</span>
            <span>{task.progress}%</span>
          </div>
          <div className={styles.progressBar}>
            <div
              className={styles.progressFill}
              style={{
                width: `${task.progress}%`,
                background: task.progress === 100 ? 'var(--success)' : undefined,
              }}
            ></div>
          </div>
        </div>
      )}
      <div className={styles.cardMeta}>
        <span>
          <i className="fas fa-tasks"></i> {task.completedSubtasks || 0}/{task.totalSubtasks || 0}
        </span>
        {task.status !== 'completed' ? (
          <SLABadge status={getSLAStatus()} timeRemaining={formatSLATime(task.slaRemaining)} compact />
        ) : (
          <span className={styles.completedBadge}>
            <i className="fas fa-check"></i> Approved
          </span>
        )}
      </div>
    </div>
  );
};
