import React from 'react';
import { Ticket } from '../../../models/Ticket';
import { useAppSelector } from '../../../store/hooks';
import { useTicketPermissions } from '../../../hooks/useTicketPermissions';
import { useResponsive } from '../../../hooks/useResponsive';
import { Button } from '../../common/Button';
import styles from './TicketActions.module.css';

export interface TicketActionsProps {
  ticket: Ticket;
  variant?: 'list' | 'detail'; // Context: list row vs detail page
  size?: 'sm' | 'md' | 'lg';
  
  // Action handlers
  onView?: (ticket: Ticket) => void;
  onEdit?: (ticket: Ticket) => void;
  onAssign?: (ticket: Ticket) => void;
  onTriage?: (ticket: Ticket) => void;
  onResolve?: (ticket: Ticket) => void;
  onClose?: (ticket: Ticket) => void;
  onRequestHelp?: (ticket: Ticket) => void;
  onAssignHelper?: (ticket: Ticket) => void;
  onReopen?: (ticket: Ticket) => void;
  
  // UI customization
  showLabels?: boolean; // Show text labels or icon-only
  alignment?: 'left' | 'center' | 'right';
  className?: string;
}

/**
 * Shared component for rendering ticket action buttons with workflow-based permissions
 * 
 * Features:
 * - Uses useTicketPermissions hook for permission checks
 * - Supports list and detail view contexts
 * - Responsive: collapses to icon-only on small screens
 * - Consistent styling and behavior across the app
 */
export const TicketActions: React.FC<TicketActionsProps> = ({
  ticket,
  variant = 'list',
  size = 'md',
  showLabels = true,
  alignment = 'right',
  // onView,
  onEdit,
  onAssign,
  onTriage,
  onResolve,
  onClose,
  onRequestHelp,
  onAssignHelper,
  onReopen,
  className,
}) => {
  const currentUser = useAppSelector((state) => state.auth.user);
  const permissions = useTicketPermissions(ticket, currentUser);
  const { isMobile } = useResponsive();

  // For list variant, show fewer actions (more compact)
  const isListView = variant === 'list';

  // On very small screens, only show icons without labels
  const showText = showLabels && !isMobile;

  return (
    <div 
      className={`
        ${styles.actions} 
        ${styles[alignment]} 
        ${styles[variant]}
        ${className || ''}
      `.trim()}
    >
      
      {/* Triage Button - Manager/Admin only, Submitted/Pending status */}
      {permissions.canTriage && onTriage && (
        <Button 
          variant="primary" 
          size={size}
          onClick={() => onTriage(ticket)}
        >
          <i className="fas fa-clipboard-check"></i>
          {showText && ' Phân Loại'}
        </Button>
      )}
      
      {/* Edit Button - Owner OR Manager/Admin */}
      {permissions.canEdit && onEdit && (
        <Button 
          variant="secondary" 
          size={size}
          onClick={() => onEdit(ticket)}
        >
          <i className="fas fa-edit"></i>
          {showText && ' Sửa'}
        </Button>
      )}
      
      {/* Assign Button - Manager/Admin, Approved/Assigned/InProgress status */}
      {permissions.canAssign && onAssign && (
        <Button 
          variant="primary" 
          size={size}
          onClick={() => onAssign(ticket)}
        >
          <i className="fas fa-user-plus"></i>
          {showText && ' Gán'}
        </Button>
      )}
      
      {/* Detail View Only Actions */}
      {!isListView && (
        <>
          {/* Resolve Button - Assignee OR Manager/Admin */}
          {permissions.canResolve && onResolve && (
            <Button 
              variant="success" 
              size={size}
              onClick={() => onResolve(ticket)}
            >
              <i className="fas fa-check-circle"></i>
              {showText && ' Giải quyết'}
            </Button>
          )}
          
          {/* Close Button - Manager/Admin, Resolved/Approved status */}
          {permissions.canClose && onClose && (
            <Button 
              variant="success" 
              size={size}
              onClick={() => onClose(ticket)}
            >
              <i className="fas fa-times-circle"></i>
              {showText && ' Đóng'}
            </Button>
          )}
          
          {/* Request Help Button - Assignee, InProgress status */}
          {permissions.canRequestHelp && onRequestHelp && (
            <Button 
              variant="warning" 
              size={size}
              onClick={() => onRequestHelp(ticket)}
            >
              <i className="fas fa-hands-helping"></i>
              {showText && ' Yêu cầu hỗ trợ'}
            </Button>
          )}
          
          {/* Assign Helper Button - Manager/Admin, HelpRequested status */}
          {permissions.canAssignHelper && onAssignHelper && (
            <Button 
              variant="primary" 
              size={size}
              onClick={() => onAssignHelper(ticket)}
            >
              <i className="fas fa-user-plus"></i>
              {showText && ' Chỉ định hỗ trợ'}
            </Button>
          )}
          
          {/* Reopen Button - Owner OR Manager/Admin, Closed status */}
          {permissions.canReopen && onReopen && (
            <Button 
              variant="warning" 
              size={size}
              onClick={() => onReopen(ticket)}
            >
              <i className="fas fa-redo"></i>
              {showText && ' Mở lại'}
            </Button>
          )}
        </>
      )}
    </div>
  );
};
