/**
 * Pure mapping: BffMessageDto → shared ChatMessage / Comment types.
 *
 * The unified BFF endpoint returns a single MessageResponseDto shape.
 * The frontend uses two different tab components (ChatTab and CommentsTab)
 * which each expect their own shape. This mapper converts the BFF DTO into both.
 */

import { ChatMessage } from '../../components/shared/ChatTab';
import { Comment } from '../../components/shared/CommentsTab';
import { BffMessageDto } from './responseModel';

/**
 * Map a BFF message (type='message') to a ChatMessage (flat, simple).
 * Used by the "Trao đổi" (Chat) tab.
 */
export const mapToChat = (dto: BffMessageDto): ChatMessage => ({
  id:         dto.id,
  entityId:   dto.entityId,
  userId:     dto.userId,
  userName:   dto.userName,
  userAvatar: dto.userAvatar,
  message:    dto.content,
  timestamp:  dto.createdAt,
});

/**
 * Map a BFF message (type='comment') to a Comment (threaded, with metadata).
 * Used by the "Bình luận" (Comments) tab.
 */
export const mapToComment = (dto: BffMessageDto): Comment => ({
  id:            dto.id,
  entityId:      dto.entityId,
  authorId:      dto.userId,
  author:        dto.userName,
  authorAvatar:  dto.userAvatar,
  content:       dto.content,
  createdAt:     dto.createdAt,
  updatedAt:     dto.updatedAt,
  parentId:      dto.parentId ?? undefined,
  reactions:     [],
  replies:       [], // Threaded replies are assembled by buildCommentTree
});

/**
 * Assemble flat list of Comments into a tree where top-level comments
 * carry nested `replies`.
 */
export const buildCommentTree = (comments: Comment[]): Comment[] => {
  const map = new Map<string, Comment>();
  const roots: Comment[] = [];

  // First pass: index all comments
  for (const c of comments) {
    map.set(c.id, { ...c, replies: [] });
  }

  // Second pass: attach children to parents
  for (const c of comments) {
    const node = map.get(c.id)!;
    if (c.parentId) {
      const parent = map.get(c.parentId);
      if (parent) {
        parent.replies = parent.replies || [];
        parent.replies.push(node);
      } else {
        roots.push(node); // orphan → treat as root
      }
    } else {
      roots.push(node);
    }
  }

  return roots;
};
